"use strict";

/**
 * PUB-4 `GET /api/v1/openapi.json`: the machine-readable description of the API (feature 004, contracts/public-api.md
 * sections 2.4 and 10). Needs the right `api.docs`, which is off for every new key (the owner can also download the same
 * document from the panel without any key). English only (U8).
 *
 * The document is generated by `lib/api/openapi.js` from the registered endpoint modules and the format registry and
 * memoised after the first build; only `servers[0].url` varies per call: the public panel URL (`PANEL_PUBLIC_URL`) plus
 * `/api/v1` when configured, else the origin the request came in on, else the relative base path. When the pipeline
 * hands the handler its own builder (`ctx.services.openapi`) that one is used (it sees the registry that is serving, a
 * temporary endpoint directory included); otherwise the default endpoint directory is loaded here (the same modules, the
 * require cache makes it one load).
 */

const path = require("node:path");
const { reply } = require("../../admin/http/response");
const { BASE_PATH } = require("../version");

const own = new WeakMap(); // formats registry -> { endpoints }

/** `https://host[:port]` of the request, or "" when the Host header is not a plain host name */
function requestOrigin(req) {
  const host = String((req.headers && req.headers.host) || "");
  if (!/^(?:[A-Za-z0-9.-]+|\[[0-9A-Fa-f:.]+\])(?::\d{1,5})?$/.test(host)) return "";
  const forwarded = String((req.headers && req.headers["x-forwarded-proto"]) || "").split(",").pop().trim().toLowerCase();
  const secure = Boolean(req.socket && req.socket.encrypted) || forwarded === "https";
  return `${secure ? "https" : "http"}://${host}`;
}

/** `PANEL_PUBLIC_URL` when it is a plain http(s) URL, else the request's own origin, else "" */
function baseUrlOf(req) {
  const configured = String(require("../../../config").PANEL_PUBLIC_URL || "").trim().replace(/\/+$/, "");
  if (/^https?:\/\/[^\s/?#]+(?:\/[^\s?#]*)?$/i.test(configured)) return configured;
  return requestOrigin(req);
}

function fallbackDocument(formats, baseUrl) {
  let entry = own.get(formats || own);
  if (!entry) {
    const { loadEndpoints } = require("../registry");
    entry = { endpoints: loadEndpoints({ dir: path.join(__dirname), formats }).endpoints };
    own.set(formats || own, entry);
  }
  const { buildOpenApi } = require("../openapi");
  return buildOpenApi({ endpoints: entry.endpoints, formats, serverUrl: baseUrl ? `${baseUrl}${BASE_PATH}` : BASE_PATH });
}

module.exports = {
  id: "openapi.get",
  method: "GET",
  path: "/api/v1/openapi.json",

  right: "api.docs",

  response: { status: 200, openapi: { type: "object", description: "An OpenAPI 3.1 document." } },

  doc: {
    summary: "OpenAPI document",
    description: "Returns the OpenAPI 3.1 description of this API: every endpoint, the thirteen message formats with an example each, the rights, the quotas and the error catalogue.",
    tags: ["documentation"],
  },

  async handle(ctx) {
    const baseUrl = baseUrlOf(ctx.req);
    const services = ctx.services;
    const document = typeof services.openapi === "function" ? services.openapi({ baseUrl }) : fallbackDocument(services.formats, baseUrl);
    return reply(200, document);
  },
};
